/**
 * Commons on PostgreSQL.
 *
 * Draws the same forum seed.mjs draws — the same rows, dated back from the
 * same day — into an empty PostgreSQL database with real types: dates as
 * date, moments as timestamp, flags as boolean, photos as bytea, the CHECKs
 * kept. Then it provisions the command journal, the record history and the
 * notification store the App needs, as the SQLite seed does, and writes `<config>` naming the
 * connection `commons`, writable.
 *
 *   node --import tsx test/fixtures/databases/commons/seed-postgres.mjs <empty-postgres-url> <new-config.json>
 *
 * The day is today in New York, the forum's, or `COMMONS_TODAY=YYYY-MM-DD`. Requires an empty
 * public schema and never drops or replaces objects. `pg` is an optional
 * repository dependency; this is a development seeder.
 */
import { existsSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import pg from 'pg';
import { migratePostgresCommandJournal } from '@mistriwork/mistri/maintenance';
import { provisionStores } from '@mistriwork/mistri/maintenance';
import { community, mail, TABLES } from './seed.mjs';
import { shopToday } from './clock.mjs';

const [url, config] = process.argv.slice(2);
if (!url || !config) {
  console.error('Usage: node --import tsx test/fixtures/databases/commons/seed-postgres.mjs <empty-postgres-url> <new-config.json>');
  process.exit(1);
}
if (existsSync(resolve(config))) throw new Error(`Refusing to replace ${config}. Choose a new config path.`);
const today = process.env.COMMONS_TODAY ?? shopToday();

/* Written by hand rather than translated from the SQLite schema: a
   translation that guessed types would make every date text on the engine
   the forum is meant to run on. In foreign-key order. Every key is an
   identity, as SQLite's INTEGER PRIMARY KEY is a rowid: a reply or a report
   inserted by a command takes the next number. */
const REASON = "check (reason in ('spam','harassment','off_topic','misinformation','other'))";
const DDL = {
  board: `create table board (id integer generated by default as identity primary key, name text not null unique, slug text not null unique,
    description text not null, position integer not null,
    status text not null default 'open' check (status in ('open','read_only')), created_on date not null)`,
  member: `create table member (id integer generated by default as identity primary key, handle text not null unique, display_name text not null,
    account_id text unique, email text unique, team text not null default 'member' check (team in ('member','moderator','admin')),
    standing text not null default 'active' check (standing in ('active','warned','suspended')),
    location text, bio text, website text, reputation integer not null default 0, joined_on date not null,
    version integer not null default 0)`,
  member_avatar: `create table member_avatar (id integer generated by default as identity primary key, member_id integer not null unique references member(id),
    file_name text not null, content_type text not null, byte_size integer not null, data bytea not null)`,
  thread: `create table thread (id integer generated by default as identity primary key, board_id integer not null references board(id),
    author_id integer not null references member(id), title text not null,
    status text not null default 'open' check (status in ('open','held','locked','removed')),
    pinned boolean not null default false, created_at timestamp not null, version integer not null default 0)`,
  post: `create table post (id integer generated by default as identity primary key, thread_id integer not null references thread(id),
    author_id integer not null references member(id), body text not null,
    status text not null default 'published' check (status in ('published','held','hidden')),
    opening boolean not null default false, created_at timestamp not null, edited_at timestamp,
    version integer not null default 0)`,
  post_image: `create table post_image (id integer generated by default as identity primary key, post_id integer not null references post(id),
    thread_id integer not null references thread(id), position integer not null, caption text not null,
    file_name text not null, content_type text not null, byte_size integer not null, data bytea not null, thumbnail bytea)`,
  post_revision: `create table post_revision (id integer generated by default as identity primary key, post_id integer not null references post(id),
    body text not null, replaced_at timestamp not null)`,
  removal: `create table removal (id integer generated by default as identity primary key, post_id integer not null references post(id),
    reason text not null ${REASON}, body text not null, note text, removed_by text, removed_at timestamp not null)`,
  reaction: `create table reaction (id integer generated by default as identity primary key, post_id integer not null references post(id),
    member_id integer not null references member(id),
    kind text not null check (kind in ('like','thanks','helpful','laugh')), created_at timestamp not null,
    unique (post_id, member_id, kind))`,
  tag: `create table tag (id integer generated by default as identity primary key, name text not null unique,
    tone text not null default 'neutral' check (tone in ('good','warn','bad','info','neutral')))`,
  thread_tag: `create table thread_tag (id integer generated by default as identity primary key, thread_id integer not null references thread(id),
    tag_id integer not null references tag(id), unique (thread_id, tag_id))`,
  report: `create table report (id integer generated by default as identity primary key, post_id integer not null references post(id),
    reason text not null ${REASON}, details text,
    status text not null default 'open' check (status in ('open','actioned','dismissed')),
    created_at timestamp not null, resolved_at timestamp, resolution text, version integer not null default 0)`,
  warning: `create table warning (id integer generated by default as identity primary key, member_id integer not null references member(id),
    reason text not null ${REASON}, note text not null, issued_by text, issued_at timestamp not null)`,
  site_image: `create table site_image (id integer generated by default as identity primary key, name text not null, file_name text not null,
    content_type text not null, byte_size integer not null, data bytea not null)`,
};
const FLAGS = new Set(['pinned', 'opening']);

const rows = community(today);
const client = new pg.Client({ connectionString: url });
await client.connect();
try {
  await client.query('begin');
  await client.query("SET LOCAL lock_timeout = '5s'");
  const lock = await client.query("SELECT pg_try_advisory_xact_lock(hashtext('tablewalk/commons/public')) AS acquired");
  if (!lock.rows[0]?.acquired) throw new Error('Another Commons seed is already running.');
  const namespace = await client.query("SELECT oid FROM pg_namespace WHERE nspname = 'public'");
  if (!namespace.rows.length) throw new Error('The public schema must exist before seeding.');
  const existing = await client.query(
    `SELECT 1 FROM pg_class WHERE relnamespace=$1
    UNION ALL SELECT 1 FROM pg_proc WHERE pronamespace=$1 UNION ALL SELECT 1 FROM pg_type WHERE typnamespace=$1 LIMIT 1`,
    [namespace.rows[0].oid],
  );
  if (existing.rows.length) throw new Error('Refusing to seed: the public schema is not empty.');
  await client.query('SET LOCAL search_path = public, pg_catalog');
  for (const table of TABLES) await client.query(DDL[table]);
  for (const table of TABLES) {
    const list = rows[table];
    if (!list.length) continue;
    const columns = Object.keys(list[0]);
    const insert = `insert into ${table} (${columns.join(', ')}) values (${columns.map((_, i) => `$${i + 1}`).join(', ')})`;
    for (const row of list)
      await client.query(
        insert,
        columns.map((column) => (FLAGS.has(column) ? Boolean(row[column]) : row[column])),
      );
    console.log(`${table.padEnd(14)} ${list.length}`);
  }
  // The rows came with their ids; the next one a command inserts takes the number after the last.
  for (const table of TABLES) {
    await client.query(`select setval(pg_get_serial_sequence('${table}', 'id'), coalesce((select max(id) from ${table}), 0) + 1, false)`);
  }
  await client.query('commit');
} catch (error) {
  await client.query('rollback').catch(() => {});
  throw error;
} finally {
  await client.end();
}
await migratePostgresCommandJournal(url);
await provisionStores({ postgres: url }, { only: ['record-history', 'inbox'] });
writeFileSync(resolve(config), `${JSON.stringify({ connections: [{ name: 'commons', url, writable: true }, mail] }, null, 2)}\n`, {
  flag: 'wx',
  mode: 0o600,
});
console.log(`\nSeeded Commons into PostgreSQL; wrote ${config}.`);
